#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import os from "node:os";
import { spawnSync } from "node:child_process";

const VERSION = "20.0.1";
const payload = [{"file":"apps/pfotentechnik/package.json","baseSha256":"e2ecd2905938bf9588f7e54ba5a9cf760e2db16eb07f21f74bc7e196c09439e4","targetSha256":"b918da8f80daf6d7ab6ef5dd0da7be30fd1f31bd80475b649f60d10d4b0c8baa","contentBase64":""},{"file":"apps/pfotentechnik/scripts/audit-editorial-transparency.mjs","baseSha256":null,"targetSha256":"fd78763afdb0572516b39fa9b2120c2c340925eb8db54dc940757d21e71580b4","contentBase64":""},{"file":"apps/pfotentechnik/src/components/EditorialTransparency.astro","baseSha256":null,"targetSha256":"37f9e0c91ce8f05f1fea7b00c8d40ab6a578222cc7f17d8d0bc41e8c37b07a67","contentBase64":""},{"file":"apps/pfotentechnik/src/content/pages/so-bewerten-wir.md","baseSha256":"e603f6934a3ea0f821c2fbb38fca8be37f4021a29044d6bf57d839842e8844f9","targetSha256":"f53cbd4a9a7407b5ea67e89b14051f1ead404ef482050dd25488f8182ec83b7d","contentBase64":""},{"file":"apps/pfotentechnik/src/pages/[slug].astro","baseSha256":"58709fa1e5f8bc033a21d5703635cd45674f8a8b5e3d8ba6dd2e27d561d7ad23","targetSha256":"42c858fb10b67539a36dc5b8658a9634b4853e0bd66030f8918cd38ce419c4ef","contentBase64":""},{"file":"apps/pfotentechnik/src/pages/affiliate-hinweis.astro","baseSha256":"f69a7c55e2ea95ba0e05171e0cb4530eb90d3cfddb6cdd00c0a82100bb6471ed","targetSha256":"64dfee9f37bedfa7ef19d26c6dc808e176ad546ff148dc5f01ead4ba4186cb65","contentBase64":""},{"file":"apps/pfotentechnik/src/pages/kontakt.astro","baseSha256":"f9d7aa435351e8ad145c0558d806b79fbf85e288546558ec06663d78aba2eb28","targetSha256":"9770b0d60531e1c4787ab4e490117b0f380fde68d29143b42d1b7b237d09bc31","contentBase64":""},{"file":"apps/pfotentechnik/src/pages/produkt/[product].astro","baseSha256":"0b40b738a5d620fec2a61ef4f7e18796fc37860483bf86ed8da993d23a625af3","targetSha256":"b40dbfd60720bfffb50aa542ee0b5aa6614920b50d0799930947d5980ba292a5","contentBase64":""},{"file":"apps/pfotentechnik/src/pages/redaktion.astro","baseSha256":null,"targetSha256":"19fee66f98878428c06d343f60397678208c0f617670d2376a048da5513430e5","contentBase64":""},{"file":"apps/pfotentechnik/src/pages/vergleiche/[comparison].astro","baseSha256":"0a83590a017b683751c921f2a4995abe248777f2773853a0296b1b3e9f363926","targetSha256":"fcaf58715533db036a7a9f9fd77456e269808b20c344a3da378daa87aadeea81","contentBase64":""},{"file":"apps/pfotentechnik/src/project.config.ts","baseSha256":"aaa50d056dd000e6eb46e7c7ce519b96a48025e2f30eb04bdaaf982b236aa324","targetSha256":"1307753811d836c2b53e9c700b12dfc007ade641fe0f82ddf5736fe7fb9c2bf2","contentBase64":""},{"file":"packages/affiliate-core/src/components/ArticleMeta.astro","baseSha256":"0206b40ac24a8236b8d9fb7ba14dd8aa81832ef9bb7a527170dfab6ff095df19","targetSha256":"531c2ee73dc22670cc87d95bc9a4bb61ef536bbcaa487abeffb3fe80760be3ea","contentBase64":""},{"file":"packages/affiliate-core/src/components/Footer.astro","baseSha256":"e2a7b2b453fd1645c99383333c0fa7e64c32d5caf095b9dac028dd5dabf6d06e","targetSha256":"67ba34f790fd7f6d6064b50efb0ec461cedbac0954e765a46cc5c6edb31cdc7d","contentBase64":""},{"file":"packages/affiliate-core/src/components/comparison/ComparisonMethodology.astro","baseSha256":"66bb853bd910e77fe1c26e5e72d03bc7106e3ab265b073884c7c561917b5a77b","targetSha256":"9a072afee1897d3520d88f58a7b8a31f771312fef8362e8b1cd56d25d3331f71","contentBase64":""},{"file":"packages/affiliate-core/src/components/home/HomeBrandStatement.astro","baseSha256":"b8adf9e82d0d9c006320d45dcb65932ad844c9f791a9486bdd37bf2964f2f0dc","targetSha256":"eeaff1bc460bdb2c01d7b166738e090363f6037a5ad815a356e6a250d053ca6e","contentBase64":""}];
const args = new Set(process.argv.slice(2));
const checkOnly = args.has("--check");
const force = args.has("--force");
const sha = (buffer) => crypto.createHash("sha256").update(buffer).digest("hex");

const findRoot = (start) => {
  let current = path.resolve(start);
  while (true) {
    if (
      fs.existsSync(path.join(current, "package.json")) &&
      fs.existsSync(path.join(current, "apps/pfotentechnik/package.json")) &&
      fs.existsSync(path.join(current, "packages/affiliate-core"))
    ) return current;
    const parent = path.dirname(current);
    if (parent === current) return null;
    current = parent;
  }
};

const root = findRoot(process.cwd());
if (!root) {
  console.error("[pfotentechnik-editorial-trust-" + VERSION + "] FEHLER: Repository-Wurzel nicht gefunden.");
  process.exit(1);
}

const state = payload.map((entry) => {
  const absolute = path.join(root, entry.file);
  const exists = fs.existsSync(absolute);
  const currentSha256 = exists ? sha(fs.readFileSync(absolute)) : null;
  const status = currentSha256 === entry.targetSha256
    ? "installed"
    : currentSha256 === entry.baseSha256 || (!exists && entry.baseSha256 === null)
      ? "ready"
      : "conflict";
  return { ...entry, absolute, exists, currentSha256, status };
});

const counts = Object.fromEntries(["installed", "ready", "conflict"].map((key) => [
  key,
  state.filter((entry) => entry.status === key).length
]));

console.log("[pfotentechnik-editorial-trust-" + VERSION + "] Vorprüfung");
console.log("Bereit: " + counts.ready + " | Bereits installiert: " + counts.installed + " | Konflikte: " + counts.conflict);

const conflicts = state.filter((entry) => entry.status === "conflict");
if (conflicts.length && !force) {
  console.error("\nAbgebrochen: Diese Dateien weichen vom erwarteten Main-Stand ab:");
  for (const entry of conflicts) console.error("- " + entry.file);
  console.error("\nAktuellen Stand prüfen oder bewusst mit --force ausführen.");
  process.exit(2);
}

if (checkOnly) {
  process.exit(conflicts.length ? 2 : 0);
}

const changes = state.filter((entry) => entry.status !== "installed");
if (!changes.length) {
  console.log("Unverändert: Editorial-Trust-System ist bereits vollständig installiert.");
  process.exit(0);
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupRoot = path.join(root, ".patch-backups", "pfotentechnik-editorial-trust-" + VERSION + "-" + stamp);
fs.mkdirSync(backupRoot, { recursive: true });

for (const entry of changes) {
  if (!entry.exists) continue;
  const backup = path.join(backupRoot, entry.file);
  fs.mkdirSync(path.dirname(backup), { recursive: true });
  fs.copyFileSync(entry.absolute, backup);
}

const written = [];
try {
  for (const entry of changes) {
    fs.mkdirSync(path.dirname(entry.absolute), { recursive: true });
    const temporary = path.join(
      path.dirname(entry.absolute),
      "." + path.basename(entry.absolute) + "." + process.pid + ".tmp"
    );
    fs.writeFileSync(temporary, Buffer.from(entry.contentBase64, "base64"));
    fs.renameSync(temporary, entry.absolute);
    written.push(entry);
  }
} catch (error) {
  for (const entry of written.reverse()) {
    const backup = path.join(backupRoot, entry.file);
    if (fs.existsSync(backup)) {
      fs.copyFileSync(backup, entry.absolute);
    } else if (entry.baseSha256 === null && fs.existsSync(entry.absolute)) {
      fs.unlinkSync(entry.absolute);
    }
  }
  console.error("Schreibvorgang fehlgeschlagen, Änderungen wurden zurückgerollt.");
  throw error;
}

for (const entry of changes) {
  const actual = sha(fs.readFileSync(entry.absolute));
  if (actual !== entry.targetSha256) {
    console.error("Integritätsprüfung fehlgeschlagen: " + entry.file);
    process.exit(3);
  }
  console.log("Geändert: " + entry.file);
}

const run = (command, commandArgs) => {
  const result = spawnSync(command, commandArgs, {
    cwd: root,
    stdio: "inherit",
    shell: process.platform === "win32"
  });
  return result.status === 0;
};

console.log("\n[pfotentechnik-editorial-trust-" + VERSION + "] Validierung");
const auditOk = run("npm", ["--workspace", "apps/pfotentechnik", "run", "audit:editorial-transparency"]);
const componentsOk = run("npm", ["--workspace", "apps/pfotentechnik", "run", "design-system:components:audit"]);

console.log("\nAbgeschlossen.");
console.log("Backups: " + path.relative(root, backupRoot));
if (!auditOk || !componentsOk) {
  console.error("Mindestens eine Validierung ist fehlgeschlagen. Änderungen und Backups bleiben erhalten.");
  process.exit(4);
}
